import numpy as np
def f(g):
    a=np.array(g); h,w=a.shape
    out=[[0]*(w//3) for _ in range(h//3)]
    for bi in range(h//3):
        for bj in range(w//3):
            b=a[bi*3:bi*3+3, bj*3:bj*3+3]
            cols=[c for r in b for c in r if c not in (0,5)]
            if cols: out[bi][bj]=max(set(cols), key=cols.count)
    return out
